-- High-version monster cards: ensure drop_data + monstercarddata mapping
-- Idempotent inserts for cards that may already exist from manual SQL.

-- Rebuild monstercarddata entries for 238xxxx from drop_data (safe upsert pattern)
DELETE FROM monstercarddata WHERE cardid >= 2386030 AND cardid <= 2387256;
SELECT itemid, MIN(dropperid) FROM drop_data
WHERE itemid >= 2386030 AND itemid <= 2387256
GROUP BY itemid;

